import numpy as np, itertools, json, sys, os
N=6
def places(L):
    out=[]
    for r in range(N):
        for c in range(N):
            if c+L<=N: out.append(tuple((r,c+i) for i in range(L)))
            if r+L<=N: out.append(tuple((r+i,c) for i in range(L)))
    return out
def nb(cells):
    s=set()
    for r,c in cells:
        for dr in(-1,0,1):
            for dc in (-1,0,1): s.add((r+dr,c+dc))
    return s
lay=[];
P={L:places(L) for L in (4,3,2)}
for a in P[4]:
  sa=set(a)
  for b in P[3]:
    if sa&set(b): continue
    for c in P[2]:
      if (sa|set(b))&set(c): continue
      lay.append((a,b,c))
M=len(lay); print(M,file=sys.stderr)
occ=np.zeros((M,36),bool); R=np.zeros((M,6),bool)
names=["any","no_touch","parallel","border","center_clear","clustered"]
ctr={(2,2),(2,3),(3,2),(3,3)}
for i,sh in enumerate(lay):
    for s in sh:
        for r,c in s: occ[i,r*6+c]=1
    ori=[s[0][0]==s[-1][0] for s in sh]
    t=[ (nb(sh[x])&set(sh[y])) for x in range(3) for y in range(3) if x!=y]
    touch=lambda x,y: bool(nb(sh[x])&set(sh[y]))
    R[i,0]=1
    R[i,1]=not(touch(0,1) or touch(0,2) or touch(1,2))
    R[i,2]=len(set(ori))==1
    R[i,3]=all(any(r in(0,5) or c in(0,5) for r,c in s) for s in sh)
    R[i,4]=not any(set(s)&ctr for s in sh)
    R[i,5]=all(any(touch(x,y) for y in range(3) if y!=x) for x in range(3))
print(R.sum(0),file=sys.stderr)
np.savez('/app/bs/lay.npz',occ=occ,R=R)
EOF
cd /app/bs && python3 m.py

