arguments.command:
cat > p.py <<'EOF'
import numpy as np, json, sys
d=np.load('lay.npz'); occ=d['occ'].astype(float); R=d['R'].astype(float)
Nr=R.sum(0); W=R/Nr  # M x 6 joint weights (rule,layout)
obs=json.load(open('obs.json')) if __import__('os').path.exists('obs.json') else []
rows=occ.reshape(-1,6,6).sum(2); cols=occ.reshape(-1,6,6).sum(1)
def slik(cnt,rep):
    p=np.zeros_like(cnt)
    for dlt,pr in((-1,.15),(0,.7),(1,.15)):
        p+=pr*(np.clip(cnt+dlt,0,6)==rep)
    return p
lik=np.ones(len(occ))
for o in obs:
    if o[0]=='f': h=occ[:,o[1]*6+o[2]]; lik*=np.where(h==o[3],.9,.1)
    else:
        cnt=(rows if o[0]=='r' else cols)[:,o[1]]; lik*=slik(cnt,o[2])
J=W*lik[:,None]; J/=J.sum()
pl=J.sum(1); pr=J.sum(0); po=(pl@occ).reshape(6,6)
names=["any","no_touch","parallel","border","center_clear","clustered"]
print(dict(zip(names,np.round(pr,4))));print(np.round(po,3))
# expected score proxy: expected entropy reduction (rule + cells/20.12*log6 weighting)
def H(p): p=np.clip(p,1e-12,1); return -(p*np.log(p)).sum()
def Hc(po): q=np.clip(po,1e-9,1-1e-9); return -(q*np.log(q)+(1-q)*np.log(1-q)).sum()
def obj(Jc):
    s=Jc.sum(); Jc=Jc/s; return H(Jc.sum(0))/np.log(6)+Hc(Jc.sum(1)@occ)/20.1236
base=obj(J); res=[]
for k in range(36):
    h=occ[:,k]; e=0
    for y in(0,1):
        L=np.where(h==y,.9,.1)[:,None]; Jc=J*L; s=Jc.sum(); e+=s*obj(Jc)
    res.append(((base-e)/1,'f',k//6,k%6))
for ax,arr in(('r',rows),('c',cols)):
    for i in range(6):
        e=0
        for rep in range(7):
            Jc=J*slik(arr[:,i],rep)[:,None]; s=Jc.sum()
            if s>1e-12: e+=s*obj(Jc)
        res.append(((base-e)/2,ax,i,None))
res.sort(reverse=True); print(res[:6])
EOF
